CREATE OR REPLACE FUNCTION public._mcp_r_get_message(p_message_id uuid, p_part integer)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $fn$
/*BODY:4263-T*/
DECLARE
  v_uid    uuid := auth.uid();
  v_st     jsonb;
  v_hide   boolean;
  v_active uuid;
  m        record;
  v_pp     jsonb;
  v_fl     jsonb;
  v_frame  jsonb;
  v_budget integer;
