           '{message,body_text}', CASE WHEN v_text IS NULL THEN 'null'::jsonb ELSE to_jsonb(v_body) END),
           '{message,part}', to_jsonb(p_part)),
           '{message,parts}', to_jsonb(v_parts));
END
