RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $fn$
/*BODY:4263-T*/
DECLARE
  v_uid    uuid := auth.uid();
  v_st     jsonb;
  v_hide   boolean;
  v_active uuid;
  v_inst   uuid;
  v_hidden boolean;
