     OR (v_st -> 'entitled') IS DISTINCT FROM to_jsonb(true)                                   /*ENT:notice:list*/
     OR (v_st -> 'switches' -> 'messages_upload') IS DISTINCT FROM to_jsonb(true) THEN         /*ENT:switch:list*/
