      'deal_id', p_deal_id,
      'messages_hidden', v_hidden,
      'messages', coalesce((SELECT jsonb_agg(pg.j ORDER BY pg.rk) FROM pg), '[]'::jsonb),
      'page', jsonb_build_object(
        'returned', (SELECT count(*) FROM pg),
